import random

# Function to get user input and validate it
def get_valid_guess():
    while True:
        try:
            user_guess = int(input("Please enter a number between 1 and 100: "))
            if 1 <= user_guess <= 100:
                return user_guess
            else:
                print("Your guess must be between 1 and 100. Please try again.")
        except ValueError:
            print("That's not a valid number. Please try again.")

# Generate a random number between 1 and 100
secret_number = random.randint(1, 100)

# Main loop
while True:
    user_guess = get_valid_guess()

    # Check if the user guessed correctly
    if user_guess == secret_number:
        print(f"Congratulations! You guessed the number correctly ({secret_number}).")
        break
    else:
        print(f"Sorry, that's not the number. The correct number was {secret_number}.")
```
This program defines a helper function `get_valid_guess()` that prompts the user for a number and validates it to ensure it's between 1 and 100. The main loop generates a random number between 1 and 100, and then repeatedly asks the user for a guess using the `get_valid_guess()` function until the user guesses correctly.
